import { useState } from 'react';
import { Outlet } from 'react-router-dom';
import { Box, CssBaseline, useTheme } from '@mui/material';
import Header from '../../components/Header';
import Sidebar from '../../components/Sidebar';
import { AIAssistantSidebar } from '../../components/AIAssistantSidebar';

const DRAWER_WIDTH = 240;
const AI_SIDEBAR_WIDTH = 450; // Tăng chiều rộng sidebar bên phải

const MainLayout = () => {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [aiSidebarOpen, setAiSidebarOpen] = useState(false);
  const theme = useTheme();

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const toggleAiSidebar = () => {
    setAiSidebarOpen(!aiSidebarOpen);
  };

  return (
    <Box sx={{ 
      display: 'flex', 
      minHeight: '100vh',
      overflowX: 'hidden',
      position: 'relative',
      width: '100%',
    }}>
      <CssBaseline />
      <Header onMenuClick={handleDrawerToggle} onAiAssistantClick={toggleAiSidebar} />
      
      {/* Sidebar bên trái - Cố định */}
      <Sidebar 
        drawerWidth={DRAWER_WIDTH} 
        mobileOpen={mobileOpen} 
        onClose={handleDrawerToggle} 
      />
      
      {/* Phần nội dung chính ở giữa - Linh hoạt theo trạng thái sidebar */}
      <Box
        component="main"
        sx={{
          flex: '1 1 auto',
          p: 3,
          marginTop: '64px',
          marginLeft: '10px',
          marginRight: aiSidebarOpen ? '10px' : 0,
          backgroundColor: theme.palette.background.default,
          minHeight: 'calc(100vh - 64px)',
          border: 'none',
          borderRadius: '8px',
          width: aiSidebarOpen ? `calc(100% - ${DRAWER_WIDTH + AI_SIDEBAR_WIDTH + 20}px)` : `calc(100% - ${DRAWER_WIDTH + 10}px)`,
          maxWidth: aiSidebarOpen ? `calc(100% - ${DRAWER_WIDTH + AI_SIDEBAR_WIDTH + 20}px)` : `calc(100% - ${DRAWER_WIDTH + 10}px)`,
          transition: theme.transitions.create(['width', 'max-width', 'margin', 'border-right'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.leavingScreen,
          }),
          overflowX: 'auto',
          '&::-webkit-scrollbar': {
            height: '8px',
          },
          '&::-webkit-scrollbar-thumb': {
            backgroundColor: theme.palette.grey[400],
            borderRadius: '4px',
          },
          '&::-webkit-scrollbar-track': {
            backgroundColor: theme.palette.grey[100],
          },
        }}
      >
        <Box sx={{ minWidth: 'fit-content' }}>
          <Outlet />
        </Box>
      </Box>
      
      {/* Sidebar bên phải - AI Assistant */}
      <Box
        sx={{
          position: 'fixed',
          top: '64px',
          right: 0,
          width: aiSidebarOpen ? `${AI_SIDEBAR_WIDTH}px` : 0,
          height: 'calc(100vh - 64px)',
          transition: theme.transitions.create(['width'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.leavingScreen,
          }),
          overflow: 'hidden',
          display: 'flex',
          backgroundColor: theme.palette.background.paper,
          border: 'none',
          borderRadius: '8px 0 0 0',
          boxShadow: aiSidebarOpen ? theme.shadows[1] : 'none',
          zIndex: 10,
        }}
      >
        <AIAssistantSidebar open={aiSidebarOpen} onClose={toggleAiSidebar}>
          {/* Nội dung AI Assistant sẽ được đặt ở đây */}
          <div>Nội dung AI Assistant</div>
        </AIAssistantSidebar>
      </Box>
    </Box>
  );
};

export default MainLayout;
