import React from 'react';
import {
  Drawer,
  Divider,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Toolbar,
  useTheme,
  useMediaQuery,
  Box,
  Typography,
  IconButton
} from '@mui/material';
import {
  Dashboard as DashboardIcon,
  People as PeopleIcon,
  MonetizationOn as DealIcon,
  Assignment as RequirementIcon,
  Receipt as QuotationIcon,
  Description as ContractIcon,
  DescriptionOutlined as AppendixIcon,
  AssignmentTurnedIn as AcceptanceIcon,
  ReceiptLong as InvoiceIcon,
  ChevronLeft,
  ChevronRight
} from '@mui/icons-material';
import { useLocation, useNavigate } from 'react-router-dom';

interface SidebarProps {
  drawerWidth: number;
  mobileOpen: boolean;
  onClose: () => void;
}

const menuItems = [
  {
    text: 'Dashboard báo cáo',
    icon: <DashboardIcon />,
    path: '/dashboard'
  },
  {
    text: 'Quản lý khách hàng',
    icon: <PeopleIcon />,
    path: '/customers'
  },
  {
    text: 'Quản lý cơ hội bán hàng (Deal)',
    icon: <DealIcon />,
    path: '/deals'
  },
  {
    text: 'Quản lý Requirement',
    icon: <RequirementIcon />,
    path: '/requirements'
  },
  {
    text: 'Quản lý báo giá / ước tính',
    icon: <QuotationIcon />,
    path: '/quotations'
  },
  {
    text: 'Quản lý hợp đồng & template hợp đồng',
    icon: <ContractIcon />,
    path: '/contracts'
  },
  {
    text: 'Quản lý phụ lục hợp đồng & template phụ lục hợp đồng',
    icon: <AppendixIcon />,
    path: '/contract-appendices'
  },
  {
    text: 'Quản lý Biên bản nghiệm thu',
    icon: <AcceptanceIcon />,
    path: '/acceptance'
  },
  {
    text: 'Quản lý Hóa đơn',
    icon: <InvoiceIcon />,
    path: '/invoices'
  }
];

const Sidebar: React.FC<SidebarProps> = ({ drawerWidth, mobileOpen, onClose }) => {
  const theme = useTheme();
  const location = useLocation();
  const navigate = useNavigate();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));


  const drawer = (
    <div>
      <Toolbar>
        <Box sx={{ display: 'flex', alignItems: 'center', width: '100%', justifyContent: 'space-between' }}>
          <Typography variant="h6" noWrap component="div" sx={{ fontWeight: 600 }}>
            CRM ITV
          </Typography>
          {!isMobile && (
            <IconButton onClick={onClose}>
              {theme.direction === 'ltr' ? <ChevronLeft /> : <ChevronRight />}
            </IconButton>
          )}
        </Box>
      </Toolbar>
      <Divider />
      <List>
        {menuItems.map((item) => (
          <React.Fragment key={item.text}>
            <ListItem disablePadding>
              <ListItemButton
                selected={location.pathname === item.path}
                onClick={() => {
                  navigate(item.path);
                  if (isMobile) onClose();
                }}
                sx={{
                  '&.Mui-selected': {
                    backgroundColor: theme.palette.action.selected,
                    '&:hover': {
                      backgroundColor: theme.palette.action.hover,
                    },
                  },
                  '&:hover': {
                    backgroundColor: theme.palette.action.hover,
                  },
                }}
              >
                <ListItemIcon sx={{ minWidth: 40 }}>
                  {React.cloneElement(item.icon, {
                    color: location.pathname === item.path ? 'primary' : 'inherit'
                  })}
                </ListItemIcon>
                <ListItemText primary={item.text} />
              </ListItemButton>
            </ListItem>
          </React.Fragment>
        ))}
      </List>
    </div>
  );

  return (
    <Box
      component="nav"
      sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}
      aria-label="mailbox folders"
    >
      {/* Mobile drawer */}
      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={onClose}
        ModalProps={{
          keepMounted: true, // Better open performance on mobile.
        }}
        sx={{
          display: { xs: 'block', sm: 'none' },
          '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
        }}
      >
        {drawer}
      </Drawer>
      
      {/* Desktop drawer */}
      <Drawer
        variant="permanent"
        sx={{
          display: { xs: 'none', sm: 'block' },
          '& .MuiDrawer-paper': { 
            boxSizing: 'border-box', 
            width: drawerWidth,
            borderRight: 'none',
            boxShadow: '2px 0 8px rgba(0,0,0,0.1)'
          },
        }}
        open
      >
        {drawer}
      </Drawer>
    </Box>
  );
};

export default Sidebar;
